Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/documents.ListView */}}
{{/* Starting point generated by WebThings: every field of the data is used below. */}}
<main id="content">
    <h1>{{.Title}}</h1>
    {{range .Documents}}
        <article>
            {{/* ID: {{.ID}} — stable, usable as an anchor */}}
            <h3>{{.Title}}</h3>
            <div>{{.Description}}</div>
            {{with .Category}}<p>{{.}}</p>{{end}}
            {{with .CategoryURL}}<a href="{{.}}">CategoryURL</a>{{end}}
            {{if not .Date.IsZero}}<time datetime="{{.Date.Format "2006-01-02T15:04:05Z07:00"}}">{{date .Date "long"}}</time>{{end}}
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
            {{if .External}}<p>External</p>{{end}}
            {{with .Filename}}<p>{{.}}</p>{{end}}
            {{with .MIMEType}}<p>{{.}}</p>{{end}}
            {{with .FileType}}<p>{{.}}</p>{{end}}
            <p>Size: {{.Size}}</p>
            {{with .SizeText}}<p>{{.}}</p>{{end}}
            <p>Downloads: {{.Downloads}}</p>
        </article>
    {{end}}
    {{range .Years}}
        <article>
            <p>Year: {{.Year}}</p>
            {{range .Documents}}
                <article>
                </article>
            {{end}}
        </article>
    {{end}}
    {{range .Categories}}
        <article>
            {{with .Name}}<p>{{.}}</p>{{end}}
            {{with .Slug}}<p>{{.}}</p>{{end}}
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
            <p>Count: {{.Count}}</p>
            {{if .Active}}<p>Active</p>{{end}}
        </article>
    {{end}}
    {{with .Category}}
        <section>
            {{with .Name}}<p>{{.}}</p>{{end}}
            {{with .Slug}}<p>{{.}}</p>{{end}}
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
            <p>Count: {{.Count}}</p>
            {{if .Active}}<p>Active</p>{{end}}
        </section>
    {{end}}
    {{with .AllURL}}<a href="{{.}}">AllURL</a>{{end}}
</main>

Types.Decl:
type APICategory struct {
	Slug string `json:"slug"`
	Name string `json:"name"`
	// DocumentCount is the number of published documents in the category.
	DocumentCount int `json:"document_count"`
	// URL is the category's list on the site, null while the instance is
	// on no page; DocumentsURL its documents in the API.
	URL          *string `json:"url"`
	DocumentsURL string  `json:"documents_url"`
}

type APIDocument struct {
	ID              string `json:"id"`
	Title           string `json:"title"`
	DescriptionHTML string `json:"description_html"`
	// Category is null for a document without a category.
	Category *APICategory `json:"category"`
	// Date is the document's own date, such as that of a meeting, at
	// midnight UTC.
	Date time.Time `json:"date"`
	// DownloadURL is the site's download address of the document, which
	// counts the download and leads to the file or the external link, as
	// on the site. External is set for a link, which has no File.
	DownloadURL string   `json:"download_url"`
	External    bool     `json:"external"`
	File        *APIFile `json:"file"`
	// URL is the document on the list of its category, or on the whole
	// list (#<id>), null while the instance is on no page; APIURL the
	// document in the API.
	URL       *string   `json:"url"`
	APIURL    string    `json:"api_url"`
	UpdatedAt time.Time `json:"updated_at"`
}

type APIFile struct {
	Filename string `json:"filename"`
	MIMEType string `json:"mime_type"`
	// FileType is the file's extension in capitals, such as "PDF"; Size is
	// in bytes.
	FileType string `json:"file_type"`
	Size     int64  `json:"size"`
}

type Document struct {
	ID          string
	Title       string
	Description template.HTML
	Category    string
	// CategoryURL lists the document's category, empty without a category or
	// when the module is not mounted.
	CategoryURL string
	// Date is a calendar date (see frontend.Civil): {{date .Date}} shows the
	// same day in every site timezone.
	Date time.Time
	// URL counts a download and redirects to the file or the link.
	URL string
	// External is true for a link instead of a file; the file details below
	// are then empty.
	External bool
	Filename string
	MIMEType string
	// FileType is the file's extension in capitals, for example "PDF".
	FileType string
	Size     int64
	// SizeText is Size for people, for example "1.2 MB".
	SizeText  string
	Downloads int
}

type Fields struct {
	File string    `db:"file_id,null"`
	Link string    `db:"link"`
	Date time.Time `db:"document_date"`
}

type ListView struct {
	// Title is the title of the page the module is mounted on, or the
	// category name when the list is filtered.
	Title string
	// Documents are newest first, filtered by Category when it is set.
	Documents []Document
	// Years hold the same documents per year, newest first.
	Years []Year
	// Categories are all categories with documents, in alphabetical order.
	Categories []Category
	// Category is the active filter, or nil.
	Category *Category
	// AllURL lists all documents.
	AllURL string
}

type Service struct {
	// contains unexported fields
}

type Text struct {
	Title       string `db:"title"`
	Description string `db:"description"`
	Category    string `db:"category"`
}

type Year struct {
	Year      int
	Documents []Document
}
